// The bundled sample lateral cephalogram (the wceph test fixture image).
// Inlined as a data: URI so loading the sample never touches the network
// (external requests are not allowed; see the design brief).
// tslint:disable:max-line-length
export const SAMPLE_CEPH_DATA_URL =
  'data:image/jpeg;base64,';
export default SAMPLE_CEPH_DATA_URL;

// The base64 payload only, past the `data:<mime>;base64,` prefix — compared
// on its own in `isSampleCephImage` below because that prefix is not a
// reliable part of "is this the same image": these exact bytes-in still land
// on a different media-type label once they round-trip through the app's own
// import pipeline. Loading the bundled sample (`store/middleware/import`'s
// LOAD_IMAGE_FROM_URL_REQUESTED handling) fetches this data: URL, wraps the
// resulting Blob in `new File([blob], 'demo_image')` with no `type` given,
// and the File constructor does not inherit one from the Blob — so the file
// reads back via FileReader as `data:application/octet-stream;base64,...`,
// pixel-for-pixel identical to this constant but never string-equal to it.
const SAMPLE_CEPH_BASE64_PAYLOAD =
  SAMPLE_CEPH_DATA_URL.slice(SAMPLE_CEPH_DATA_URL.indexOf(',') + 1);

/**
 * Whether `data` carries exactly the bundled sample film's bytes above — the
 * one image `predictors/demo.ts`' placeholder template was calibrated
 * against. Anything else (including a re-encoded copy that merely *looks*
 * the same) reads as false on purpose: `predictors/demo.ts`' fractions are
 * honest only for these exact bytes, not for a lookalike. Compares only the
 * base64 payload, not the `data:` URL's media-type prefix — see
 * `SAMPLE_CEPH_BASE64_PAYLOAD` above for why that prefix cannot be trusted.
 */
export const isSampleCephImage = (data: string | null | undefined): boolean => {
  if (typeof data !== 'string') {
    return false;
  }
  const comma = data.indexOf(',');
  return comma !== -1 && data.slice(comma + 1) === SAMPLE_CEPH_BASE64_PAYLOAD;
};
